//! What the password, token and encryption steps call: argon2id hashing off the async runtime, a dummy hash for
//! unknown accounts, random tokens, SHA-256, and AES-256-GCM for what is stored at rest.
//!
//! @generated by service-builder. Do not edit: changes are overwritten on the next export.

use std::sync::LazyLock;

use aes_gcm::aead::{Aead, AeadCore, KeyInit, OsRng};
use aes_gcm::{Aes256Gcm, Nonce};
use anyhow::Result;
use argon2::{Argon2, PasswordHash, PasswordHasher, PasswordVerifier};
use sha2::{Digest, Sha256};

use crate::http::HttpError;

/// argon2 costs CPU and memory, so a gigantic "password" would be a denial of service.
pub const MAX_PASSWORD_BYTES: usize = 1024;

/// Checked when the account is unknown, so that the answer takes as long as a real refusal.
static DUMMY_HASH: LazyLock<String> = LazyLock::new(|| {
    Argon2::default()
        .hash_password(b"dummy password")
        .expect("the dummy hash")
        .to_string()
});

/// argon2id, as a PHC string (`$argon2id$...`). It runs in `spawn_blocking`: it is slow on purpose and
/// would otherwise freeze every other request of the runtime.
pub async fn hash_password(password: String) -> Result<String> {
    if password.len() > MAX_PASSWORD_BYTES {
        return Err(HttpError::bad_request("password too long").into());
    }
    tokio::task::spawn_blocking(move || {
        Argon2::default()
            .hash_password(password.as_bytes())
            .map(|hash| hash.to_string())
            .map_err(|e| anyhow::anyhow!("cannot hash the password: {e}"))
    })
    .await?
}

/// Whether `password` matches `stored`. `None` is an unknown account: the check runs against the dummy
/// hash and answers `false`. A stored text that is not a hash never matches either.
pub async fn verify_password(password: String, stored: Option<String>) -> bool {
    if password.len() > MAX_PASSWORD_BYTES {
        return false;
    }
    tokio::task::spawn_blocking(move || {
        let known = stored.is_some();
        let hash = stored.unwrap_or_else(|| DUMMY_HASH.clone());
        let Ok(parsed) = PasswordHash::new(&hash) else {
            return false;
        };
        let ok = Argon2::default()
            .verify_password(password.as_bytes(), &parsed)
            .is_ok();
        ok && known
    })
    .await
    .unwrap_or(false)
}

/// 256 random bits as 64 hexadecimal characters.
pub fn random_token() -> String {
    let mut bytes = [0u8; 32];
    rand::fill(&mut bytes);
    hex::encode(bytes)
}

/// SHA-256 as 64 hexadecimal characters: what is stored of a token, which is already random enough
/// that a fast hash is enough.
pub fn sha256_hex(text: &str) -> String {
    hex::encode(Sha256::digest(text.as_bytes()))
}

const NONCE_LEN: usize = 12;

/// The 32-byte key of an encryption step, as 64 hexadecimal characters in the environment variable `env_name`.
/// A service that has such a step fails at start-up when it is missing or malformed.
pub fn key(env_name: &str) -> Result<[u8; 32]> {
    let text = std::env::var(env_name)
        .map_err(|_| anyhow::anyhow!("{env_name} is not set: nothing can be encrypted or decrypted"))?;
    let bytes = hex::decode(text.trim())
        .map_err(|_| anyhow::anyhow!("{env_name} must be 64 hexadecimal characters (32 bytes)"))?;
    <[u8; 32]>::try_from(bytes.as_slice())
        .map_err(|_| anyhow::anyhow!("{env_name} must be 64 hexadecimal characters (32 bytes), not {}", bytes.len() * 2))
}

fn seal(key: &[u8; 32], plaintext: &[u8]) -> Result<Vec<u8>> {
    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| anyhow::anyhow!("invalid AES key"))?;
    // A fresh random nonce each time: the same text never seals to the same bytes.
    let nonce = Aes256Gcm::generate_nonce(&mut OsRng);
    let mut sealed = nonce.to_vec();
    sealed.extend(
        cipher
            .encrypt(&nonce, plaintext)
            .map_err(|_| anyhow::anyhow!("encryption failed"))?,
    );
    Ok(sealed)
}

fn open(key: &[u8; 32], sealed: &[u8]) -> Result<Vec<u8>> {
    if sealed.len() <= NONCE_LEN {
        anyhow::bail!("sealed data too short");
    }
    let (nonce, ciphertext) = sealed.split_at(NONCE_LEN);
    let nonce = <[u8; NONCE_LEN]>::try_from(nonce)?;
    Aes256Gcm::new_from_slice(key)
        .map_err(|_| anyhow::anyhow!("invalid AES key"))?
        .decrypt(&Nonce::from(nonce), ciphertext)
        .map_err(|_| anyhow::anyhow!("cannot decrypt: wrong key, or the data was altered"))
}

/// The step: AES-256-GCM, returned as `hex(nonce || ciphertext || tag)`.
pub fn encrypt(key_env: &str, plaintext: &str) -> Result<String> {
    Ok(hex::encode(seal(&key(key_env)?, plaintext.as_bytes())?))
}

/// The step: what [`encrypt`] sealed. A wrong key, a truncated or an altered value is an error: the stored
/// data is not what this service wrote.
pub fn decrypt(key_env: &str, sealed: &str) -> Result<String> {
    let bytes = hex::decode(sealed.trim()).map_err(|_| anyhow::anyhow!("sealed data is not hexadecimal"))?;
    Ok(String::from_utf8(open(&key(key_env)?, &bytes)?)?)
}

#[cfg(test)]
mod tests {
    use super::*;

    const KEY: [u8; 32] = [7; 32];

    #[test]
    fn what_another_implementation_sealed_opens() {
        // Sealed by Python's `cryptography` (AES-GCM) with this key and the nonce 00..0b: the format is the
        // standard one, `nonce || ciphertext || tag`.
        let sealed = hex::decode("000102030405060708090a0b52c3ba27443a9d1932fab5d7d10834aa63def7ed70d2ef74e344fbd6898c7bf5").unwrap();
        assert_eq!(open(&KEY, &sealed).unwrap(), b"JBSWY3DPEHPK3PXP");
    }

    #[test]
    fn a_text_comes_back_and_each_sealing_differs() {
        let sealed = seal(&KEY, b"JBSWY3DPEHPK3PXP").unwrap();
        assert_eq!(open(&KEY, &sealed).unwrap(), b"JBSWY3DPEHPK3PXP");
        assert_ne!(seal(&KEY, b"x").unwrap(), seal(&KEY, b"x").unwrap());
        // The nonce, the text and the 16-byte tag.
        assert_eq!(sealed.len(), NONCE_LEN + "JBSWY3DPEHPK3PXP".len() + 16);
    }

    #[test]
    fn a_wrong_key_a_truncation_and_an_alteration_are_refused() {
        let mut sealed = seal(&KEY, b"secret").unwrap();
        assert!(open(&[8; 32], &sealed).is_err());
        assert!(open(&KEY, &sealed[..5]).is_err());
        assert!(open(&KEY, &sealed[..NONCE_LEN]).is_err());
        // Any bit: the nonce, the text, the tag.
        for at in [0, NONCE_LEN, sealed.len() - 1] {
            sealed[at] ^= 1;
            assert!(open(&KEY, &sealed).is_err(), "byte {at}");
            sealed[at] ^= 1;
        }
        assert!(open(&KEY, &sealed).is_ok());
    }

    #[test]
    fn the_steps_read_their_key_from_the_environment() {
        // SAFETY: only this test touches these variables.
        unsafe {
            std::env::set_var("EDA_TEST_KEY", "07".repeat(32));
            std::env::set_var("EDA_TEST_SHORT_KEY", "07".repeat(31));
            std::env::set_var("EDA_TEST_BAD_KEY", "zz".repeat(32));
        }
        let sealed = encrypt("EDA_TEST_KEY", "héllo ✓").unwrap();
        assert!(sealed.bytes().all(|b| b.is_ascii_hexdigit()));
        assert_eq!(decrypt("EDA_TEST_KEY", &sealed).unwrap(), "héllo ✓");
        assert!(decrypt("EDA_TEST_KEY", "not hex").is_err());
        assert!(decrypt("EDA_TEST_KEY", &sealed[..sealed.len() - 2]).is_err());
        // A key that is missing, short or not hexadecimal is refused with its name, never used.
        for (name, expected) in [("EDA_TEST_NO_KEY", "is not set"), ("EDA_TEST_SHORT_KEY", "62"), ("EDA_TEST_BAD_KEY", "hexadecimal")] {
            let message = key(name).unwrap_err().to_string();
            assert!(message.contains(name) && message.contains(expected), "{message}");
        }
    }

    #[tokio::test]
    async fn a_password_verifies_against_its_own_hash_only() {
        let hash = hash_password("a correct password".into()).await.unwrap();
        assert!(hash.starts_with("$argon2id$"));
        assert!(verify_password("a correct password".into(), Some(hash.clone())).await);
        assert!(!verify_password("another password".into(), Some(hash)).await);
    }

    #[tokio::test]
    async fn an_unknown_account_or_a_corrupted_hash_never_verifies() {
        assert!(!verify_password("dummy password".into(), None).await);
        assert!(!verify_password("x".into(), Some("not a hash".into())).await);
    }

    #[tokio::test]
    async fn a_huge_password_is_refused_before_argon2_runs() {
        let huge = "a".repeat(MAX_PASSWORD_BYTES + 1);
        let error = hash_password(huge.clone()).await.unwrap_err();
        assert_eq!(error.downcast_ref::<HttpError>().unwrap().status, 400);
        assert!(!verify_password(huge, None).await);
    }

    /// The runtime of `#[tokio::test]` has one thread: hashing straight in the async task would freeze the ticker.
    #[tokio::test]
    async fn hashing_does_not_starve_the_runtime() {
        use std::sync::Arc;
        use std::sync::atomic::{AtomicU32, Ordering};
        use std::time::Duration;
        let ticks = Arc::new(AtomicU32::new(0));
        let counter = ticks.clone();
        let ticker = tokio::spawn(async move {
            loop {
                tokio::time::sleep(Duration::from_millis(1)).await;
                counter.fetch_add(1, Ordering::SeqCst);
            }
        });
        tokio::time::sleep(Duration::from_millis(5)).await;
        let before = ticks.load(Ordering::SeqCst);
        hash_password("a correct password".into()).await.unwrap();
        let during = ticks.load(Ordering::SeqCst) - before;
        ticker.abort();
        assert!(during > 0, "the runtime froze while hashing");
    }

    #[test]
    fn tokens_are_long_hex_and_never_repeat() {
        let (a, b) = (random_token(), random_token());
        assert_ne!(a, b);
        assert_eq!(a.len(), 64);
        assert!(a.bytes().all(|c| c.is_ascii_hexdigit()));
    }

    #[test]
    fn sha256_matches_the_known_vector() {
        assert_eq!(
            sha256_hex("abc"),
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        );
        assert_ne!(sha256_hex("abc"), sha256_hex("abd"));
    }
}
